+                    + processFunction.warnExceptions.stream().map(m -> "$T").collect(Collectors.joining(" | "))
+                    + " e)";
+                builder.nextControlFlow(catchPattern, processFunction.warnExceptions.stream().map(m -> TypeName.get(m)).toArray());
